// Parse AI response
const aiOutput = $input.item.json.output || $input.item.json.text || '';

let decision = 'DESIGN_VERGESSEN';
let customerType = 'GESCHAEFT';
let confidence = 0.5;
let reasoning = 'Konnte KI-Antwort nicht parsen';

try {
  const jsonMatch = aiOutput.match(/\{[\s\S]*?\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    decision = parsed.decision || decision;
    customerType = parsed.customerType || customerType;
    confidence = parsed.confidence || confidence;
    reasoning = parsed.reasoning || reasoning;
  }
} catch (e) {
  if (aiOutput.toLowerCase().includes('bewusst_kein_design')) {
    decision = 'BEWUSST_KEIN_DESIGN';
  }
  if (aiOutput.toLowerCase().includes('privat')) {
    customerType = 'PRIVAT';
  }
}

// Get original email data from IF node
const emailData = $('Hat Anhang?').item.json;

// RAW output: body.content contains full HTML
let bodyContent = '';
if (emailData.body && typeof emailData.body === 'object' && emailData.body.content) {
  bodyContent = emailData.body.content;
} else if (typeof emailData.body === 'string') {
  bodyContent = emailData.body;
} else if (emailData.bodyPreview) {
  bodyContent = emailData.bodyPreview;
}

let vorname = '';
let nachname = '';
let customerEmail = '';

// Known form field labels used as delimiters for bodyPreview parsing
const fieldLabels = ['Name','Vorname','Nachname','Firma','E-Mail','Telefon','Produkt','Farbe','Groesse','Größe','Ort','Zeitrahmen','Website','Quelle','Design','Request-ID','Nachricht','Kommentar','Anmerkung'];
const delimiterPattern = fieldLabels.map(l => l.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|');

// ============================================
// HELPER: Wert aus HTML extrahieren
// Unterstuetzt 4 Formate:
//   1. <strong>Label</strong>: Wert
//   2. <td>Label:</td><td>Wert</td> (Tabelle)
//   3. Label: Wert (bodyPreview) — mit naechstem Feld als Delimiter
//   4. E-Mail spezifisch: Email-Pattern Extraktion
// ============================================
function extractField(html, label) {
  let m;
  // Format 1: <strong>Label</strong>: Wert
  m = html.match(new RegExp('<strong>' + label + '</strong>\\s*:\\s*([^<\\r\\n]+)', 'i'));
  if (m && m[1]) return m[1].trim();
  m = html.match(new RegExp(label + '</strong>:\\s*([^<\\r\\n]+)', 'i'));
  if (m && m[1]) return m[1].trim();
  // Format 2: <td...>Label:</td><td...>Wert</td> (Tabelle)
  m = html.match(new RegExp('<td[^>]*>\\s*' + label + ':\\s*</td>\\s*<td[^>]*>\\s*([^<]*)', 'i'));
  if (m) return (m[1] || '').trim();
  // Format 3+4: bodyPreview mit Delimiter
  if (emailData.bodyPreview) {
    // Spezialfall E-Mail: direkt Email-Pattern extrahieren
    if (label === 'E-Mail') {
      m = emailData.bodyPreview.match(/E-Mail:\s*([^\s@]+@[^\s@]+\.[^\s@]+)/i);
      if (m && m[1]) return m[1].trim();
    }
    // Allgemein: Match bis zum naechsten bekannten Feld-Label
    m = emailData.bodyPreview.match(new RegExp(label + ':\\s*(.+?)(?=(?:' + delimiterPattern + '):|$)', 'i'));
    if (m && m[1]) return m[1].replace(/<[^>]*>/g, '').trim();
  }
  return '';
}

// 1. Vorname extrahieren (altes Formular)
vorname = extractField(bodyContent, 'Vorname');

// 2. Fallback: Name-Feld (neues Formular) -> Vorname extrahieren
if (!vorname || vorname === '-') {
  const fullName = extractField(bodyContent, 'Name');
  if (fullName && fullName !== '-') {
    const parts = fullName.split(/\s+/);
    vorname = parts[0];
    if (parts.length > 1) nachname = parts.slice(1).join(' ');
  }
}

// E-Mail extrahieren
customerEmail = extractField(bodyContent, 'E-Mail');

// Nachname nur wenn noch nicht gesetzt
if (!nachname) {
  nachname = extractField(bodyContent, 'Nachname');
  if (nachname === '-') nachname = '';
}

vorname = vorname.replace(/<[^>]*>/g, '').replace(/^\s+|\s+$/g, '');
customerEmail = customerEmail.replace(/<[^>]*>/g, '').replace(/^\s+|\s+$/g, '');
nachname = nachname.replace(/<[^>]*>/g, '').replace(/^\s+|\s+$/g, '');

// E-Mail Fallback: from-Adresse (nur wenn nicht die eigene)
if (!customerEmail && emailData.from) {
  if (typeof emailData.from === 'object' && emailData.from.emailAddress) {
    const fromAddr = emailData.from.emailAddress.address;
    if (!fromAddr.includes('neontrip.de')) {
      customerEmail = fromAddr;
    }
  } else if (typeof emailData.from === 'string' && !emailData.from.includes('neontrip.de')) {
    customerEmail = emailData.from;
  }
}

// E-Mail Validierung: Muss ein @ und einen Punkt enthalten
const isValidEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(customerEmail);
if (!isValidEmail) {
  customerEmail = '';
}

if (!vorname || vorname === '-') vorname = 'Kunde';

console.log(`[PARSE] Name: ${vorname} ${nachname} | Email: ${customerEmail} | Decision: ${decision} | Valid: ${isValidEmail}`);

// Conservative send gate:
// Upstream nodes already filtered to: old enough, not our own email,
// no Outlook attachment, no design field value, and no file/upload URL.
// Send only when the customer likely forgot a file, not when they describe
// a text/sign that NEONTRIP should design from scratch.
function plain(value) {
  return String(value || '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/\s+/g, ' ')
    .trim();
}

const messageText = plain(
  extractField(bodyContent, 'Nachricht') ||
  extractField(bodyContent, 'Kommentar') ||
  extractField(bodyContent, 'Anmerkung') ||
  emailData.bodyPreview ||
  ''
);
const normalizedMessage = messageText.toLowerCase();
const compactMessage = normalizedMessage.replace(/[^a-z0-9äöüß]+/gi, '');

const hasAttachmentReference = /\b(anbei|anhang|angehaengt|angehängt|beigefuegt|beigefügt|hochgeladen|upload|datei|vektor|pdf|svg|eps|png|jpe?g)\b/i.test(normalizedMessage);
const hasLogoReference = /\b(mein|meine|unser|unsere|das|dem|vom)?\s*(logo|design|grafik|datei|vorlage)\b/i.test(normalizedMessage);
const isEmptyOrMinimal = compactMessage.length < 18 || /^(hallo|bitte|angebot|preis|anfrage|neonschild|led|ledneonschild|test)$/i.test(compactMessage);
const asksOnlyForPrice = /\b(preis|kosten|angebot|kostenvoranschlag)\b/i.test(normalizedMessage) && compactMessage.length < 45;
const describesDesignToCreate = /\b(schriftzug|spruch|slogan|text|wort|woerter|wörter|buchstaben|name|namen|schreibschrift|kursiv|blockschrift|font|schriftart|gestalten|designen|entwerfen|soll\s+(stehen|lauten)|drauf\s*(stehen|sein))\b/i.test(normalizedMessage) || /["'“”„][^"'“”„]{2,}["'“”„]/.test(messageText);

const deterministicMissingDesign =
  !describesDesignToCreate &&
  (isEmptyOrMinimal || asksOnlyForPrice || hasAttachmentReference || hasLogoReference);

const shouldSendReminder = deterministicMissingDesign && isValidEmail;
const shouldSendConfigurator = false;
const sendDecisionSource = shouldSendReminder
  ? 'conservative_forgot_upload_gate'
  : (!isValidEmail ? 'blocked_invalid_customer_email' : 'blocked_customer_describes_design_or_unclear');

return {
  json: {
    decision,
    customerType,
    confidence,
    reasoning,
    shouldSendReminder,
    shouldSendConfigurator,
    sendDecisionSource,
    deterministicMissingDesign,
    customer: {
      vorname,
      nachname,
      email: customerEmail
    },
    originalEmail: {
      id: emailData.id,
      subject: emailData.subject,
      conversationId: emailData.conversationId
    }
  }
};

// Nur E-Mails verarbeiten die mindestens 10 Minuten alt sind
// Damit der AutoReply (6 Min Wait) zuerst ankommt
const TEN_MINUTES_MS = 10 * 60 * 1000;
const now = Date.now();
const results = [];

for (const item of $input.all()) {
  const received = item.json.receivedDateTime || item.json.createdDateTime;
  if (!received) {
    // Kein Datum -> sicherheitshalber durchlassen
    results.push(item);
    continue;
  }
  const age = now - new Date(received).getTime();
  if (age >= TEN_MINUTES_MS) {
    results.push(item);
  } else {
    console.log(`[AGE-FILTER] Skip: E-Mail erst ${Math.round(age / 1000)}s alt (< 10 Min)`);
  }
}

console.log(`[AGE-FILTER] ${results.length} von ${$input.all().length} E-Mails sind alt genug`);
return results;

// Dedup-Gate: Jede relevante Kandidaten-Email wird max. 3x verarbeitet, mit 30 Min Cooldown
// v4: Retry erst nach Design-/Attachment-Filtern; alte v3-Zaehler werden bewusst ignoriert
const staticData = $getWorkflowStaticData('global');
if (!staticData.processedEmails_v4) staticData.processedEmails_v4 = {};

const MAX_RETRIES = 3;
const COOLDOWN_MS = 30 * 60 * 1000; // 30 Minuten zwischen Versuchen
const CLEANUP_AGE_MS = 7 * 24 * 60 * 60 * 1000; // 7 Tage
const now = Date.now();

// Alte Eintraege aufraeumen
for (const [id, entry] of Object.entries(staticData.processedEmails_v4)) {
  if (now - entry.firstSeen > CLEANUP_AGE_MS) {
    delete staticData.processedEmails_v4[id];
  }
}

const results = [];
let skipped = 0;
let cooldown = 0;

for (const item of $input.all()) {
  const emailId = item.json.id;
  if (!emailId) { results.push(item); continue; }

  if (!staticData.processedEmails_v4[emailId]) {
    staticData.processedEmails_v4[emailId] = { count: 0, firstSeen: now, lastAttempt: 0 };
  }

  const entry = staticData.processedEmails_v4[emailId];

  // Max Versuche erreicht -> dauerhaft skippen
  if (entry.count >= MAX_RETRIES) {
    skipped++;
    continue;
  }

  // Cooldown: Nicht zu oft verarbeiten
  if (entry.count > 0 && (now - entry.lastAttempt) < COOLDOWN_MS) {
    cooldown++;
    continue;
  }

  entry.count++;
  entry.lastAttempt = now;

  console.log(`[RETRY] Email ${emailId.substring(0, 40)}... -- Versuch ${entry.count}/${MAX_RETRIES}`);
  results.push(item);
}

if (skipped > 0) console.log(`[RETRY] ${skipped} Email(s) uebersprungen (max Versuche erreicht)`);
if (cooldown > 0) console.log(`[RETRY] ${cooldown} Email(s) im Cooldown`);
console.log(`[RETRY] ${results.length} von ${$input.all().length} Emails zur Verarbeitung`);

return results;

// FILTER: Eigene Emails + Design-Check im Body
// Filtert raus:
// 1. Emails VON neontrip.de (eigene Antworten) -- AUSSER LP-Benachrichtigungen
// 2. Emails wo der Kunde bereits ein Design hochgeladen hat
// 3. Emails mit Datei-URLs im Body (NerdyForms Uploads)

const results = [];

for (const item of $input.all()) {
  const email = item.json;

  // 1. Eigene Emails rausfiltern (aber LP-Benachrichtigungen durchlassen)
  let fromAddress = '';
  if (email.from && email.from.emailAddress) {
    fromAddress = email.from.emailAddress.address || '';
  } else if (typeof email.from === 'string') {
    fromAddress = email.from;
  }

  const body = email.body?.content || '';
  const preview = email.bodyPreview || '';
  const fullText = body + ' ' + preview;
  const subject = email.subject || '';

  // LP-Benachrichtigungen erkennen (von neontrip.de, aber Formular-Notification)
  const isLpNotification = (
    fullText.includes('Neue Anfrage ueber Landing Page') ||
    fullText.includes('Neue Anfrage \u00fcber Landing Page') ||
    (subject.includes('Neue Anfrage') && fullText.includes('Request-ID:')) ||
    (subject.includes('Neue Anfrage') && fullText.includes('E-Mail:') && fullText.includes('Produkt:'))
  );

  if (fromAddress.toLowerCase().includes('neontrip.de') && !isLpNotification) {
    console.log(`[DESIGN-CHECK] Skip: Eigene Email von ${fromAddress}`);
    continue;
  }

  // 2. Design-Feld im Body pruefen
  let designValue = '';

  // Format: <strong>Design</strong>: Ja/Nein/URL
  let m = fullText.match(/<strong>Design<\/strong>\s*:\s*([^<\r\n]+)/i);
  if (m) designValue = m[1].trim();

  // Format: <td>Design:</td><td>Wert</td>
  if (!designValue) {
    m = fullText.match(/<td[^>]*>\s*Design:\s*<\/td>\s*<td[^>]*>\s*([^<]*)/i);
    if (m) designValue = m[1].trim();
  }

  // Format: Design: Wert (bodyPreview)
  if (!designValue) {
    m = preview.match(/Design:\s*(.+?)(?=\s+(?:Request-ID|Nachricht|Kommentar|Quelle|$))/i);
    if (m) designValue = m[1].trim();
  }

  if (designValue && designValue !== 'Nein' && designValue !== '-' && designValue !== '') {
    console.log(`[DESIGN-CHECK] Skip: Design vorhanden = "${designValue}"`);
    continue;
  }

  // 3. Datei-URLs im Body pruefen
  const urlPatterns = [
    /https?:\/\/[^\s"<]+\.(?:png|jpg|jpeg|gif|svg|pdf|ai|eps|cdr)/i,
    /https?:\/\/storage\.googleapis\.com/i,
    /https?:\/\/[^\s"<]*nerdyforms[^\s"<]*/i,
    /https?:\/\/[^\s"<]*uploads?[^\s"<]*\.(?:png|jpg|jpeg|gif|svg|pdf|ai|eps)/i
  ];
  let hasFileUrl = false;
  for (const pattern of urlPatterns) {
    if (pattern.test(fullText)) { hasFileUrl = true; break; }
  }
  if (hasFileUrl) {
    console.log(`[DESIGN-CHECK] Skip: Datei-URL im Body gefunden`);
    continue;
  }

  console.log(`[DESIGN-CHECK] Durchgelassen: ${email.subject?.substring(0, 50)}`);
  results.push(item);
}

console.log(`[DESIGN-CHECK] ${results.length} von ${$input.all().length} Emails ohne Design`);
if (results.length === 0) return [];
return results;
